#!/usr/bin/env node
/**
 * Guards for the press kit (/press and /zh/press).
 *
 * A press kit is the one page whose whole job is to be copied. That makes two
 * failure modes expensive and invisible: a figure that drifted away from
 * contracts/params.json, and a download link to a file that was renamed or
 * never committed -- the second one 404s only after somebody has already
 * published the link. Both are asserted here.
 *
 * Generated by website/tools/build_press.py -- edit that, not the HTML.
 */

import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";
import { test } from "node:test";

const ROOT = new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1");
const WEB = ROOT + "website";
const params = JSON.parse(readFileSync(ROOT + "contracts/params.json", "utf8"));
const a = params.airdrop;

const EN = WEB + "/press.html";
const ZH = WEB + "/zh/press.html";
const en = existsSync(EN) ? readFileSync(EN, "utf8") : "";
const zh = existsSync(ZH) ? readFileSync(ZH, "utf8") : "";

function ldBlocks(html) {
  return [...html.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)]
    .map((m) => JSON.parse(m[1]));
}

const th = (n) => n.toLocaleString("en-US");

test("the press kit exists in both languages", () => {
  assert.ok(existsSync(EN), "English press kit is missing — run website/tools/build_press.py");
  assert.ok(existsSync(ZH), "Chinese mirror is missing — run website/tools/build_press.py");
});

test("both pages publish parseable structured data and the right canonical", () => {
  for (const [name, html, lang, url] of [
    ["en", en, "en", "https://omc.network/press"],
    ["zh", zh, "zh-Hans", "https://omc.network/zh/press"],
  ]) {
    const blocks = ldBlocks(html);
    assert.ok(blocks.length >= 2, `${name}: expected Organization + WebPage blocks`);
    const page = blocks.find((b) => b["@type"] === "WebPage");
    assert.ok(page, `${name}: no WebPage block`);
    assert.equal(page.inLanguage, lang, `${name}: wrong inLanguage`);
    assert.equal(page.url, url, `${name}: WebPage url must be the canonical URL`);
    assert.equal(page.isAccessibleForFree, true, `${name}: a press kit that is paywalled is not a press kit`);
    assert.ok(blocks.some((b) => b["@type"] === "Organization"), `${name}: no Organization block`);
    assert.equal(
      blocks.find((b) => b["@type"] === "BreadcrumbList") !== undefined,
      true,
      `${name}: no BreadcrumbList`,
    );
    assert.ok(html.includes(`<link rel="canonical" href="${url}">`), `${name}: canonical tag missing`);
  }
});

test("hreflang points at each version from both pages", () => {
  for (const [name, html] of [["en", en], ["zh", zh]]) {
    assert.ok(html.includes('hreflang="en" href="https://omc.network/press"'), `${name}: no en hreflang`);
    assert.ok(html.includes('hreflang="zh" href="https://omc.network/zh/press"'), `${name}: no zh hreflang`);
    assert.ok(html.includes('hreflang="x-default"'), `${name}: no x-default`);
  }
});

test("every airdrop figure matches contracts/params.json", () => {
  // A press kit quotes the numbers a journalist will reproduce without checking.
  for (const [name, html] of [["en", en], ["zh", zh]]) {
    assert.ok(html.includes(th(a.pool)), `${name}: pool ${a.pool} missing or not thousands-separated`);
    assert.ok(html.includes(`${a.perEntry} OMC`), `${name}: per-entry ${a.perEntry} missing`);
    assert.ok(html.includes(th(a.poolSlots)), `${name}: slot count ${a.poolSlots} missing`);
    const fee = String(a.claimCost.feeBnb);
    assert.ok(html.includes(`${fee} BNB`), `${name}: claim fee ${fee} BNB missing`);
    assert.ok(html.includes("BEP-20"), `${name}: must say BEP-20`);
    assert.ok(html.includes("2027"), `${name}: must state the 2027 TGE`);
  }
});

test("nothing on the page calls it a purchase, a presale or a paid airdrop", () => {
  // Same ban list the feed and the announcement are held to. The press kit is
  // where a wrong framing would be copied furthest, so it is checked hardest.
  const banned = ["entrance fee", "paid airdrop", "cost to enter", "buy the airdrop", "presale is", "入场费"];
  for (const [name, html] of [["en", en], ["zh", zh]]) {
    const lower = html.toLowerCase();
    for (const phrase of banned) {
      assert.ok(!lower.includes(phrase), `${name}: must not say "${phrase}"`);
    }
  }
});

test("the claim fee is described as a processing charge, next to the claim", () => {
  assert.match(en, /processing (charge|fee)/i, "en: the fee must be named as a processing charge");
  assert.match(zh, /处理手续费/, "zh: 费用必须被称作处理手续费");
});

test("every download link resolves to a file in the repository", () => {
  const hrefs = new Set();
  for (const html of [en, zh]) {
    for (const m of html.matchAll(/href="(\/assets\/[^"]+|\/og-image\.png)"[^>]*download>/g)) {
      hrefs.add(m[1]);
    }
  }
  assert.ok(hrefs.size >= 5, `expected at least 5 downloadable assets, found ${hrefs.size}`);
  for (const href of hrefs) {
    assert.ok(existsSync(WEB + href), `${href} is linked with download but does not exist in website/`);
  }
});

test("every image on the page has alt text", () => {
  for (const [name, html] of [["en", en], ["zh", zh]]) {
    const imgs = [...html.matchAll(/<img\b[^>]*>/g)].map((m) => m[0]);
    assert.ok(imgs.length > 0, `${name}: no images at all`);
    for (const tag of imgs) {
      assert.match(tag, /alt="[^"]+"/, `${name}: image without alt text: ${tag.slice(0, 80)}`);
    }
  }
});

test("the page is reachable from the footer, the sitemap and llms.txt", () => {
  // A press kit nobody links to is a 404 with a nicer title. Three entry points
  // are checked because each one serves a different reader: humans (footer),
  // crawlers (sitemap), answer engines (llms.txt).
  const index = readFileSync(WEB + "/index.html", "utf8");
  assert.ok(index.includes('href="/press"'), "index.html footer does not link to /press");

  const sitemap = readFileSync(WEB + "/sitemap.xml", "utf8");
  assert.ok(sitemap.includes("<loc>https://omc.network/press</loc>"), "sitemap has no /press");
  assert.ok(sitemap.includes("<loc>https://omc.network/zh/press</loc>"), "sitemap has no /zh/press");

  const llms = readFileSync(WEB + "/llms.txt", "utf8");
  assert.ok(llms.includes("https://omc.network/press"), "llms.txt does not list /press");
});

test("the boilerplate is present in three lengths and claims no price", () => {
  assert.match(en, /One line/, "en: missing the one-line boilerplate");
  assert.match(en, /Short &middot;/, "en: missing the short boilerplate");
  assert.match(en, /Full &middot;/, "en: missing the full boilerplate");
  // There is no OMC price. Any sentence that states one is a fabrication.
  assert.ok(!/\$\s?0?\.\d+\s*(per|a)\s*OMC/i.test(en), "en: states a per-OMC price");
  assert.ok(!/OMC\s+(is|trades)\s+at\s+\$/i.test(en), "en: states an OMC price");
});
